INSERT INTO `catalog_pages` VALUES (16, 874, '', 'Aydınlatma', 'default_3x3', 1, 24651, 1, 2, '1', '1', '0', '0', 'catalog_dimmers_header1_en', 'catalog_dimmer_teaser_en', '', 'Check out the Mood Lights. Use these items to dim the light in your rooms. Try out different light settings with different wallpapers to see what you get. Talk about lighting with style!', NULL, NULL, 'Click on an item for details.', 0, '');
INSERT INTO `catalog_pages` VALUES (464, 402, '2008', '2008 - Kumdan Kale', 'default_3x3', 1, 274, 1, 1, '1', '1', '0', '0', 'summer', 'catalog_teaser_cch_furni', '', 'Who hasn\'t dreamt of making a sandcastle they fit in? Now you can!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (503, 209, 'jet_set', 'Jet Sosyete', 'default_3x3', 1, 237, 1, 10, '0', '0', '0', '0', 'jetset_header', 'jetset_yachtcomp', '', 'Live life to the fullest with our Jetset furni range. This is the Furni fen those Habbos who like to throw obscenely huge parties and show off their style.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (17, 568, 'mode', 'Mod', 'default_3x3', 1, 39, 1, 16, '1', '1', '0', '0', 'catalog_mode_headline1', 'catalog_mode_teaser1', '', 'Steely functionality combined with a sleek designer upholstery. The Habbo who chooses this furniture is a cool urban cat - streetwise, sassy and so slightly untouchable.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (179, 180, 'aqua_pura', 'Su Purası', 'default_3x3_color_grouping', 1, 48, 1, 1, '1', '1', '0', '0', 'puraheader', 'catalog_pura_teaser1', '', 'This collection breathes fresh, clean air and cool tranquility. Use it to create a haven away from the hullabaloo of the public spaces or your life outside the hotel.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (3034, 669, '', 'Paskalya Çatlakları', 'default_3x3', 1, 42, 7, 1, '1', '1', '0', '0', '', '', '', NULL, NULL, NULL, NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (281, 568, 'area', 'Alan', 'default_3x3', 1, 14, 1, 3, '1', '1', '0', '0', 'catalog_area_headline1', 'catalog_area_teaser1', '', 'A chunky and sofisticated line for the down-to-earth, It\'s simplicty is beautful and will add a welcoming charm to every room.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (282, 209, 'country', 'Ülke', 'default_3x3', 1, 21, 1, 3, '1', '1', '0', '0', 'country_header1_en_001', 'country_teaser1', '', '\"Moving to the country, gonna eat a lot of peaches\"... The great outdoors is calling with the Country Furni range!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (277, 4, 'pet_animals', 'Evcil Hayvanlar Hayvanlar', 'pets3', 1, 18753, 1, 2, '1', '1', '0', '0', 'catalog_pet_headline1_en', 'ctlg_pet_note', '', 'Pets are inhabitants of Habbo Hotel so each pet owner needs to know a bit about them. If you want to look after your pet properly, make sure you read the following points carefully.', 'A few things you should know:', '*You can place a pet in your room or take one for a walk with you in other rooms.\n*You can\'t trade your pet but they can follow you to friend\'s rooms to gather scratches.\n*You can have up to 50 pets in your room, but look after them all!\n\n\n*Look after your pet with food, water and treats. Check the Pets\' Accessories.\n*Unlock Badges and Achievements by Training your Pet.', 'Click your Pet and hit the \"Train\" button to get a list of commands that will level up your Pet in no time!', 0, '');
INSERT INTO `catalog_pages` VALUES (18, 568, 'lodge', 'Kulübe', 'default_3x3', 1, 37, 1, 15, '1', '1', '0', '0', 'catalog_lodge_headline1', 'catalog_lodge_teaser1', '', 'For that splendid ski-lodge effect with an open fire and whisky on the sidebar. This range is for those who appreicate the true beauty of solid wood.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (19, 511, 'colourable_plasto', 'Boyanabilir Plasto', 'default_3x3_color_grouping', 1, 46, 1, 1, '1', '1', '0', '0', 'plastic', 'plastic_pasic_promo_1', '', 'Throw on an afro and grab a disco ball! Feel that retro, 1970s vibe? You soon will with this colourful, plastic range! Choose a colour to suit your mood and off you go!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (182, 604, 'bathroom', 'Banyo', 'default_3x3', 1, 4552, 1, 3, '1', '1', '0', '0', 'bathroom_catahead', 'bcbath_catateaser', '', 'Give yourself and your guests somewhere to freshen up - vital if you want to avoid nasty smells. Might be an idea to put your loo in a corner though.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (20, 602, 'gardening', 'Bitkiler ve Çiçekler', 'default_3x3', 1, 4608, 1, 5, '1', '1', '0', '0', 'catalog_plants_headline1', 'catalog_plants_teaser1', '', 'Every room needs a plant! Not only do they bring a bit of the outside inside, they also enhance the air quality! And what better gift for a friend than a beautiful rose or elegant fruit tree...', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (559, 604, 'carpets', 'Halılar', 'default_3x3', 1, 116, 1, 4, '1', '1', '0', '0', 'catalog_rugs_headline1', 'catalog_rugs_teaser1', '', 'Rugs for all occasions, all non-slip and washable.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (21, 568, 'walls', 'Duvar Dekorasyonları', 'default_3x3', 1, 219, 1, 9, '1', '1', '0', '0', 'catalog_walls_header_dyn', 'catalog_walls_teaser2_001', '', 'Bring the outdoors in with windows and posters. Transform your surroundings - your walls will never look bare again!', '', '', '', 0, '');
