INSERT INTO `catalog_pages` VALUES (24, 568, 'base', 'Temel', 'default_3x3', 1, 179, 1, 4, '1', '1', '0', '0', 'catalog_header_base', 'base_rentable_teaser', '', 'This colourful range of furni has everything you need to style out your room and build deat spaces.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (299, 376, '2014_health_spa', '2014 - Sağlık Spası', 'default_3x3', 1, 62, 1, 11, '1', '1', '0', '0', 'catalog_header_spa', 'catalog_teaser_spa', '', 'Sometimes, all you want is a nice relaxing spa day. With this furni line, you can enjoy one with your Valentine!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (25, -1, '', 'Rozetler', 'default_3x3', 1, 875, 1, 5, '1', '1', '0', '0', 'catalog_header_badgedisplay', 'badgedisplay_promo2', '', 'You worked hard to get your badges, right? Now\'s the time to show it off, grab a display case and choose your favorite badge to show off!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (27, 568, 'iced', 'Buzlu', 'default_3x3', 1, 72, 1, 14, '1', '1', '0', '0', 'catalog_iced_headline1', 'catalog_iced_teaser1', '', 'It\'s so chic, it says everything and nothing. It\'s a blank canvas, let your imagination run wild!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (28, 209, 'alhambra', 'Elhamra', 'default_3x3', 1, 12, 1, 1, '1', '1', '0', '0', 'alhambra_header', 'alhambra_teaser', '', 'For the cold Arabian nights and hot Arabian days, you\'ll need a palace.. And we have just what you need! Green blossom print should cover it just fine!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (302, 209, 'asian', 'Asya', 'default_3x3', 1, 15, 1, 1, '1', '1', '0', '0', 'catalog_asian_headline1', 'catalog_asian_teaser1', '', 'Ting tong! Ching chong? Ting chong ting, ping ping! I mean uh.. with our authentic Chinese furniture, you can make a beautiful oriental room!', '', '', '', 0, '');
