INSERT INTO `catalog_pages` VALUES (106, 209, 'boutique', 'Butik', 'default_3x3', 1, 74, 1, 2, '1', '1', '0', '0', 'boutique_catalog_01', 'boutique_catalog_teaser_01', '', 'The boutique range is just the thing if you want to own a high end fashion store in Milan, but are on a budget.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (365, 387, 'club_mammoth', 'Kulüp Mammoth', 'default_3x3', 1, 264, 1, 3, '1', '1', '0', '0', 'catalog_header_classics', 'jan18_classic11_internal', '', 'Club Mammoth was first opened to only HC and VIP (when it was introduced) members. The room description was \"Monumental and magnificant.\"', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (364, 387, 'star_lounge', 'Yıldız Salonu', 'default_3x3', 1, 264, 1, 21, '1', '1', '0', '0', 'catalog_header_classics', 'spromo_Star_Lounge', '', 'While also popular, this room was also used for many Celebrity Visits.', '', '', '', 0, '');
