INSERT INTO `catalog_pages` VALUES (362, 387, 'ice_cafe', 'Buz Kafe', 'default_3x3', 1, 264, 1, 14, '1', '1', '0', '0', 'catalog_header_classics', 'classic5_furnis', '', 'The Ice Cafe was used a a meeting place in Habbo Experience for Chaplin and his friends.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (107, 2, 'zabbo_groups', 'Habbo Grupları', 'guilds', 1, 203, 1, 11, '1', '1', '0', '0', 'catalog_groups_en', 'catalog_groupsteaser_en', '', 'Habbo Groups are a great way to stay in touch with your friends and share your interests with others. Each Group has a homeroom that can be decorated by other Group members, members can also purchase exclusive Group Furni that can be customised with your Group colours!', '', '* Get together with people you get together with!\r\n* Co-op room decorating for group members\r\n* Show off your group badge!\r\n* Get some neat Furni in your group\'s colours!', 'What\'s So Great About Habbo Groups?', 0, '');
INSERT INTO `catalog_pages` VALUES (108, 107, 'group_furni', 'Grup Mobilyaları', 'guild_furni', 1, 203, 1, 1, '1', '1', '0', '0', 'catalog_groups_en', '', 'guild_custom_furni', 'Show off your Group spirit with the new customisable Furni. Select your Group and then get your furni in your Groups colours.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (377, 372, 'new_years', 'Yeni Yıl', 'default_3x3', 1, 91, 1, 5, '1', '0', '0', '0', '', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (109, 209, 'youtube', 'Youtube', 'default_3x3', 1, 188, 1, 25, '1', '1', '0', '0', 'catalog_header_tv', 'yttv', '', 'Remember when Habbo had YouTube TVs? Well it can again, with KrewsTube! Check it out at krews.org', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (110, 209, 'vikings', 'Vikingler', 'default_3x3', 1, 208, 1, 23, '1', '1', '0', '0', 'vikings_catalog_header', 'catalog_teaser_vikings', '', 'From weapon racks and heads on spikes, to ornate hand-carved wooden chairs and benches. This furni has everything you need and more to create the Viking village of your dreams. With furni available in clan colours, you can display your true loyalty with pride!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (111, 209, '0', 'Palooza', 'default_3x3', 1, 227, 1, 3, '1', '1', '0', '0', 'catalog_teaser_palooza', 'catalog_teaser_palooza', '', 'Create your own stage and outdoor festival area. We\'ve got stages, fencing and even vending machines!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (112, 209, 'wild_wild_west', 'Vahşi Vahşi Batı', 'default_3x3', 1, 229, 1, 24, '1', '1', '0', '0', 'catalog_header_wwest', 'catalog_teaser_wildwest', '', 'From the Shoot\'em Up Saloon to the Sheriff\'s Office, and all the floor tiles, cacti and tumbleweeds in between...Wild West furni has made it\'s way to town.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (113, 387, 'club_nx', 'Kulüp NX', 'default_3x3', 1, 264, 1, 4, '1', '1', '0', '0', 'catalog_header_classics', 'catal_fp_pic5', '', 'On Habbo, there is a door at the top next to the bar that leads to Hallway 2.', '', '', '', 0, '');
