INSERT INTO `catalog_pages` VALUES (158, 209, 'army_bootcamp', 'Ordu Eğitim Kampı', 'default_3x3', 1, 259, 1, 1, '1', '1', '0', '0', 'catalog_header_army15', 'army_newfurni', '', 'Purchase the new in stock army/military based furni - from gun racks to choppers, no matter what item you\'re after; this section will have it!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (159, 387, 'infobus', 'Bilgi otobüsü', 'default_3x3', 1, 264, 1, 15, '1', '1', '0', '0', 'catalog_header_classics', 'catal_fp_pic5', '', 'The famous Infobus was only ever opened when staff were hosting events or discussions, whereas the park was always open.', '', '', '', 0, '');
