INSERT INTO `catalog_pages` VALUES (161, 209, 'paris', 'Paris', 'default_3x3', 1, 261, 1, 17, '1', '1', '0', '0', 'paris_header', 'paris_teaser', '', 'Always wanted to build a Paris designed room? Now is your chance with this brand new set of Paris furniture.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (162, 387, 'hall_of_habbo', 'Habbo Salonu', 'default_3x3', 1, 264, 1, 9, '1', '1', '0', '0', 'catalog_header_classics', 'catal_fp_pic5', '', 'It is the least used Public Room, and features users who have won various competitions.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (378, 374, 'classics', 'Klasikler', 'default_3x3', 1, 181, 1, 1, '1', '1', '0', '0', 'catalog_easter_headline1', 'catalog_easter_teaser1', '', 'Little birdies hatching from their eggs, pretty, dainty flowers blooming and cute rabbits bouncing in Spring meadows.. it\'s Easter!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (494, 209, 'heroic_acts_certificate', 'Kahramanca Eylemler Sertifikası', 'default_3x3', 1, 210, 1, 8, '0', '0', '0', '0', '', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (163, 107, 'groups_forums', 'Gruplar Forumlar', 'guild_forum', 1, 207, 1, 2, '1', '1', '0', '0', 'catalog_groups_en', '', '', 'Group Forums are here!', '', '<b><font color=\"#0e3f52\" size=\"16\">What are Group Forums?</font></b>\r\n\r\nForums allow you to effortlessly post, comment and discuss topics freely, without even leaving the Hotel!\n\n<i><b><font color=\"#0e3f52\" size=\"16\">Who can start a forum? </font></b></i>\n\nOnly a group owner can start a forum for their group.\n\n<i><b><font color=\"#0e3f52\" size=\"16\">Do I need a Forum Terminal?</font></b></i>\n\nYes - In order to start a Group Forum the group owner must first purchase a forum terminal for the group.\n\n\nFind out more about Group Forums <a href=\"event:habbopages/forums\">here</a>.\n\nPlease note, we will continue to add more functionalities to this feature in the near future.', '', 0, '');
