INSERT INTO `catalog_pages` VALUES (455, 376, '2014_white_bling', '2014 - Beyaz Parıltı', 'default_3x3', 1, 62, 1, 13, '1', '1', '0', '0', 'catalog_header_val12', 'catalog_love_teaser1', '', 'Did someone speak in glamour? Chic? Lux? So you\'re speaking the language of Bonnie Blonde, my friend! Now in white!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (240, 376, '2013_love_locks', 'Fonksiyonel Aşk Kilitleri', 'default_3x3', 1, 62, 1, 2, '1', '1', '0', '0', 'catalog_header_val12', 'val14_lovelock3', '', 'Friendship Padlocks are Furni that show how special your friends are. You and your friend need to be in your room. Put the Padlock in the Room, click 2x on it, and confirm the action. Once closed, your friendship will be saved forever, even if you trade it!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (241, 240, '2014_l0-v3_machines', 'AŞK Makineleri', 'default_3x3', 1, 62, 1, 12, '1', '1', '0', '0', 'valentines_catalog_header', 'lovelock_s_promo', '', 'Put your love to the test! Lock in your Valentine for life with these Machines.', '', '', '', 0, '');
