INSERT INTO `catalog_pages` VALUES (242, 234, 'saddles', 'Eyerler', 'petcustomization', 1, 135, 1, 3, '1', '1', '0', '0', 'catalog_saddles_header2_en', 'sadddles', '', 'To use a saddle, place it in a room where you have at least one Horse. Double click the saddle and select what horse you want to ride After placing the saddle you can ride your Horse by clicking on it and selecting \'Ride\'.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (453, 376, '2008_habborella', '2008 - Habborella', 'default_3x3', 1, 62, 1, 1, '1', '1', '0', '0', 'catalog_val_headline1_en', 'valentine_furni_001', '', 'Find your true love with the Love Randomiser, and how better to celebrate than with a box of chocolates?', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (243, 234, 'dyes', 'Boyalar', 'petcustomization', 1, 133, 1, 4, '1', '1', '0', '0', 'catalog_horsedyes_header2_en', 'dyes', '', 'Customize your horse with this selection of hair colours and body types. Each dye can also be added to your room as a piece of furniture. To use a dye place it to your room, double click on it and then select the horse you want to customise.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (452, 376, '2010_heartbreak_hotel', '2010 - Kalp Kırıklığı Oteli', 'default_3x3', 1, 62, 1, 4, '1', '1', '0', '0', 'catalog_header_val12_2_en', 'catalog_love_teaser1', '', 'A gift basket and a cuddly teddy for your Valentine, and some cozy seats for your date.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (244, 234, 'hair_styles', 'Saç Modelleri', 'petcustomization', 1, 134, 1, 5, '1', '1', '0', '0', 'catalog_horsehairstyles2_header_en', 'hairs', '', 'Customize your horse and make him unique with this selection of hair styles.  Each style can also be added to your room as a piece of furniture. To use a hair style place it to your room, double click on it and then select the horse you want to customise.', '', '', '', 0, '');
