INSERT INTO `catalog_pages` VALUES (449, 376, '2017_wedding', 'Bir Düğün Planlayın', 'default_3x3', 1, 62, 1, 3, '1', '1', '0', '0', 'catalog_header_val12', 'catalog_love_teaser1', '', 'Do I hear wedding bells? The perfect outdoor setting awaits!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (246, 4, 'monster_plants', 'Canavar Bitkiler', 'pets3', 1, 153, 1, 6, '1', '1', '0', '0', 'catalog_header_mopla_01', 'ctlg_monster_note', '', 'Monster Plants can sure be a handful, this page gives you some extra advice on raising and looking after your monsterous brood.', 'Taking Care Of Your Plant', 'Your plants need to be tended regularly, or else they die. To ensure a healthy plant tend it every 30 hours\nor so. If it dies, you can use the Revival potion to\nbring it back to life.\nBreeding\nTo breed your plant you have to wait until it\'s fully\ngrown. Clicking Breed on the menu will show you\nwhat other plants in the room are available to breed\nwith.', '', 0, '');
INSERT INTO `catalog_pages` VALUES (448, 376, '2019_restaurant', '2019 - Restoran', 'default_3x3', 1, 62, 1, 17, '1', '1', '0', '0', 'catalog_header_val12_2_en', 'val19_newfurni', '', 'Perfect for a romantic evening with your loved one.\n', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (247, 246, 'monster_plant_seeds', 'Canavar Bitki Tohumları', 'default_3x3', 1, 156, 1, 1, '1', '1', '0', '0', 'catalog_header_mnstrSeeds', 'quest_teaser_monsterplants', '', 'Plant your seeds in your room and tend to keep them alive and healthy. After your plants have matured you can breed your plants to try and get leveled up offspring. Plants can only breed once without using the Rebreeding Potion.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (446, 376, '2012_prom', '2012 - Balo', 'default_3x3', 1, 62, 1, 7, '1', '1', '0', '0', 'valentin2012-1', 'catalog_love_teaser1', '', 'Prom is full of crying teens and bad dance moves, but it\'s always a fond memory for many. Create your perfect prom with this furni!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (447, 376, '2012_getaway', '2012 - Kaçış', 'default_3x3', 1, 62, 1, 6, '1', '1', '0', '0', 'Valentines_header', 'catalog_love_teaser1', '', 'Even plants can find love, and share alongside Habbos. Put your love to the test with the Love Thermometer and Kissing Booth!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (248, 246, 'monster_plant_potions', 'Canavar Bitki İksirleri', 'default_3x3', 1, 155, 1, 2, '1', '1', '0', '0', 'monsterplantsprays_header', 'monsterplantspray_teaser', '', 'On this page you\'ll find everything you need to take care of your plants: Plant Revival for when your plants die. Place potion to room, double click and select the plant you want to revive.', '', '', '', 0, '');
