INSERT INTO `catalog_pages` VALUES (79, 277, 'bears', 'Ayılar', 'pets', 1, 68, 1, 1, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'A large mammal that walks on the soles of its feet, with thick fur and a short tail. Did you know that bears are related to dogs and that most species are omnivorous?', 'Name your Bear:', NULL, 'Pick a breed:', 0, '');
