INSERT INTO `catalog_pages` VALUES (879, 2, 'information_classic', 'Bilgi', 'pets3', 1, 22222, 1, 1, '1', '1', '0', '0', '', 'catalog_icon', '', 'Welcome to the official catalog of Zabbo.ME, created and maintained by Justin.<br><br> For ease of use, check out the Creators tab.<br>Are we missing a furni line you want? Reach out to justinretros on Discord to request it!', 'Welcome to Zabbo Catalog v1', '<img src=\"data:image/png;base64,\" align=\"right\"></a>Enjoy building? Well, we\'ve got just the catalog for you! For ease of use, check out the Creators tab, where you will find neatly organized categories to help spend you less time searching the catalog and more time building beautiful rooms!<br><br><b>Are we missing a furni line you want to see on Zabbo?</b><br> Post a suggestion in our <a href=\"https://discord.gg/zabbo\" target=\"_blank\"><b>Discord</b></a> with the furniture line\'s name, and a screenshot of the items and we will add it ASAP!', '<img src=\"data:image/gif;base64,\" align=\"left\" style=\"padding-right: 5px;margin-top: -2px;\">This catalog is maintained by <b>Justin</b>.', 0, '');
