INSERT INTO `catalog_pages` VALUES (8970, 7, 'information_staff', 'Bilgi', 'pets3', 1, 22222, 7, 0, '1', '1', '0', '0', '', 'catalog_icon', '', '', 'Staff Rares :: Rules', '<img src=\"data:image/png;base64,\" align=\"right\">Before going any further, it is important to note, and follow the rules we have set out to ensure Zabbo maintains a fair and stable economy. Failure to abide by the following rules will result in your immediate termination and account wipe.<br><br>1) Do not give out any rares in this section to regular users without authorization from Management.<br>2)You may use these items to build, however you must own the room you are using them to build in.<br>3) You may not trade, transfer, or otherwise move any furnitur from this section; this includes moving it into a public category using the Catafix commands.', '<img src=\"data:image/gif;base64,\" align=\"left\" style=\"padding-right: 5px;margin-top: -2px;\">Your purchases and trade logs are monitored by Hotel Management.', 0, '');
